import javax.xml.bind.JAXBContext
import javax.xml.bind.Marshaller

class Bad {
    private val marshaller: Marshaller = JAXBContext.newInstance(Bad::class.java).createMarshaller() // bad: not thread-safe
}

import jakarta.xml.bind.JAXBContext
import jakarta.xml.bind.Unmarshaller

class Bad {
    private val unmarshaller: Unmarshaller = JAXBContext.newInstance(Bad::class.java).createUnmarshaller() // bad
}

import javax.xml.bind.JAXBContext
import javax.xml.bind.Validator

@Suppress("DEPRECATION")
class Bad {
    private val validator: Validator = JAXBContext.newInstance(Bad::class.java).createValidator() // bad
}

import javax.xml.bind.JAXBContext

class Good {
    companion object {
        private val CTX = JAXBContext.newInstance(Good::class.java)
    }
    fun marshal(obj: Good) {
        val marshaller = CTX.createMarshaller() // ok: local variable is thread-safe
        marshaller.marshal(obj, java.io.StringWriter())
    }
}

import javax.xml.bind.JAXBContext import javax.xml.bind.Marshaller
val CTX = JAXBContext.newInstance(String::class.java)
fun marshalAll(items: List<String>) = items.map { item -> val m: Marshaller = CTX.createMarshaller() // ok: created per invocation inside lambda java.io.StringWriter().also { m.marshal(item, it) }.toString() }
